void Solver::restart() {
    // Reset LBD statistics
    fast_lbd_sum = 0;
    lbd_queue_size = 0;
    lbd_queue_pos = 0;
    slow_lbd_sum = 0;

    // Backtrack to root level
    backtrack(0);

    // Decay activity scores and re‑insert all variables into VSIDS heap
    for (int v = 1; v <= vars; ++v) {
        activity[v] *= 0.5;
        if (!vsids.inHeap(v)) vsids.insert(v);
    }
    var_inc = 1.0;  // reset variable increment factor

    // Rephase variables with a new random strategy
    int r = rand() % 100;
    if (r < 30) {
        // Use the best local assignment found so far
        for (int i = 1; i <= vars; ++i) saved[i] = local_best[i];
    } else if (r < 55) {
        // Use the opposite of the best local assignment
        for (int i = 1; i <= vars; ++i) saved[i] = -local_best[i];
    } else if (r < 80) {
        // Random polarity for each variable
        for (int i = 1; i <= vars; ++i) saved[i] = (rand() & 1) ? 1 : -1;
    } else {
        // Keep the current saved phases (no change)
    }

    // Reset thresholds for rephase and reduce to avoid premature triggers
    threshold = trail.size();
    rephase_limit = 8192;
    reduce_limit = 512;
}
